package com.trekconnect.ai.service;

import com.trekconnect.ai.dto.request.ChatMessage;
import com.trekconnect.ai.dto.request.TrekBotChatRequest;
import com.trekconnect.ai.dto.request.TrekContextPayload;
import com.trekconnect.ai.dto.response.TrekBotChatResponse;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.util.*;
import java.util.regex.Pattern;

/**
 * Context-Aware Ollama-Powered RAG Chatbot Service.
 * 
 * ARCHITECTURE:
 * 1. Dedicated Ollama LLM: All responses are exclusively generated by local Ollama.
 * 2. In-JVM Template Engine Removed: When Ollama is offline, TrekBot directly informs the user that the service is unavailable.
 * 3. Dynamic RAG Grounding: Retrieves verified trail data and safety guidelines to ground Ollama prompts.
 * 4. Anti-Hallucination Guardrails: Prevents off-topic usage.
 */
@Service
public class TrekBotRagService {

    private final TrekKnowledgeBaseService knowledgeBaseService;
    private final OllamaAiClientService ollamaClient;

    @Value("${trekbot.guardrails.enabled:true}")
    private boolean guardrailsEnabled = true;

    // Off-topic patterns to enforce strict mountain expedition domain guardrails
    private static final Pattern OFF_TOPIC_PATTERN = Pattern.compile(
        "(?i)\\b(python|javascript|java program|write code|crypto|bitcoin|election|politics|movie review|recipe for cake|recipe for|homework|hack|sql injection|nba|cricket score|stock market|football match|who won|essay on|tell me a joke|relationship advice)\\b"
    );

    public TrekBotRagService(TrekKnowledgeBaseService knowledgeBaseService, OllamaAiClientService ollamaClient) {
        this.knowledgeBaseService = knowledgeBaseService;
        this.ollamaClient = ollamaClient;
    }

    public TrekBotChatResponse generateResponse(TrekBotChatRequest request) {
        String userQuery = request.getUserMessage() != null ? request.getUserMessage().trim() : "";
        if (userQuery.isEmpty()) {
            return TrekBotChatResponse.builder()
                    .reply("Hello adventurer! I am **TrekBot**, your AI mountain expedition guide powered by Ollama. How can I assist you with your upcoming expedition?")
                    .groundedIn("TrekConnect Assistant")
                    .confidenceScore(1.0)
                    .suggestedFollowUps(Arrays.asList("What treks are near Nashik?", "What should I pack for high altitude?", "Recommend treks near Pune"))
                    .build();
        }

        // 1. Domain Guardrails Check
        if (guardrailsEnabled && isOffTopic(userQuery)) {
            return TrekBotChatResponse.builder()
                    .reply("I am TrekBot, your dedicated mountain expedition assistant! I specialize strictly in trekking itineraries, trail difficulty, gear advice, packing lists, weather safety, and booking details across all mountain regions. For non-trekking topics, please explore the appropriate forums or contact support.")
                    .groundedIn("TrekBot Domain Guardrails")
                    .confidenceScore(1.0)
                    .isOffTopic(true)
                    .suggestedFollowUps(Arrays.asList(
                            "What is the trail difficulty?",
                            "What gear do I need for this trek?",
                            "What meals are included?"
                    ))
                    .build();
        }

        // 2. Strict Ollama Service Availability Check
        if (!ollamaClient.isAvailable()) {
            return buildOllamaOfflineResponse();
        }

        // 3. Resolve Multi-Turn Context & Target Trek Details
        TrekContextPayload ctx = request.getTrekContext();
        if (ctx == null) {
            ctx = synthesizeDefaultContext(request.getTrekTitle(), request.getTrekId());
        }

        String effectiveQuery = resolveContextualQuery(userQuery, request.getConversationHistory());
        String lowerQuery = effectiveQuery.toLowerCase(Locale.ENGLISH);

        // 4. Recommendation & Trail Discovery via Ollama
        if (isRecommendationQuery(lowerQuery)) {
            List<TrekKnowledgeBaseService.TrekRecommendation> recs = knowledgeBaseService.findRecommendedTreks(effectiveQuery);
            StringBuilder recContext = new StringBuilder();
            for (TrekKnowledgeBaseService.TrekRecommendation r : recs) {
                recContext.append(String.format("- %s (%s, %d ft, %s): %s [Distance: %s]\n",
                        r.name, r.cityRegion, r.altitudeFt, r.difficulty, r.highlights, r.distance));
            }

            String recSysPrompt = "You are TrekBot, an expert mountaineering expedition assistant for TrekConnect. " +
                    "The user is asking for trail recommendations or nearby treks across India/global trails. " +
                    "Recommend the most suitable options from the verified trail database provided below. " +
                    "Highlight altitude, difficulty, distance, and key scenery. " +
                    "Keep your response concise, well-structured with bullet points, and enthusiastic.";

            String userPrompt = String.format("Verified Trail Options:\n%s\n\nUser Question: %s", recContext, userQuery);
            Optional<String> llmOutput = ollamaClient.generateResponse(recSysPrompt, userPrompt);
            if (llmOutput.isPresent()) {
                return TrekBotChatResponse.builder()
                        .reply(llmOutput.get())
                        .groundedIn(String.format("Ollama (%s) & Regional Trek Directory", ollamaClient.getModelName()))
                        .confidenceScore(0.99)
                        .suggestedFollowUps(buildRecommendationFollowUps(recs))
                        .build();
            }
            // If Ollama timed out or failed to respond
            return buildOllamaOfflineResponse();
        }

        // 5. Trek-Specific Itinerary, Gear, Safety or General Inquiry via Ollama
        String systemPrompt = String.format(
            "You are TrekBot, an expert mountaineering expedition AI assistant for TrekConnect. " +
            "You support treks across ALL regions (Himalayas, Western Ghats, Nilgiris, North-East, and worldwide). " +
            "Ground your answers in the provided expedition parameters. Never hallucinate fake trail details. " +
            "Trek: '%s' | Location: '%s' | Peak Altitude: %s ft | Difficulty: '%s' | Price: INR %s. " +
            "Prioritize trekker safety, altitude sickness precautions (if high altitude), and Leave-No-Trace mountain ethics. " +
            "Keep the reply concise, practical, and formatted in clean markdown.",
            ctx.getTitle(), ctx.getLocation(), ctx.getAltitudeFt(), ctx.getDifficulty(), ctx.getPricePerSlot()
        );

        String userPromptWithContext = String.format(
            "Trek Parameters:\n" +
            "- Inclusions: %s\n" +
            "- Exclusions: %s\n" +
            "- Date/Schedule: %s\n\n" +
            "User Question: %s",
            ctx.getInclusions(), ctx.getExclusions(), ctx.getUpcomingDate(),
            userQuery
        );

        Optional<String> llmOutput = ollamaClient.generateResponse(systemPrompt, userPromptWithContext);
        if (llmOutput.isPresent()) {
            return TrekBotChatResponse.builder()
                    .reply(llmOutput.get())
                    .groundedIn(String.format("Ollama (%s) & %s", ollamaClient.getModelName(), ctx.getTitle()))
                    .confidenceScore(0.99)
                    .suggestedFollowUps(Arrays.asList(
                            "What gear do I need for this terrain?",
                            "What is the trail difficulty and fitness requirement?",
                            "What meals and permits are included?"
                    ))
                    .build();
        }

        // If Ollama timed out or failed to respond
        return buildOllamaOfflineResponse();
    }

    private TrekBotChatResponse buildOllamaOfflineResponse() {
        return TrekBotChatResponse.builder()
                .reply("⚠️ **TrekBot AI Assistant is currently offline.**\n\n" +
                       "The AI reasoning service (Ollama) is not running or is unavailable. " +
                       "Please ensure the Ollama service is active (`ollama run llama3.2:3b`) on the server to chat with TrekBot.")
                .groundedIn("Ollama Service Offline")
                .confidenceScore(0.0)
                .suggestedFollowUps(Collections.emptyList())
                .build();
    }

    private String resolveContextualQuery(String currentQuery, List<ChatMessage> history) {
        if (history == null || history.isEmpty() || currentQuery.length() > 40) {
            return currentQuery;
        }
        String lower = currentQuery.toLowerCase(Locale.ENGLISH);
        if (containsAny(lower, "what about", "how about", "and", "also", "tell me more", "is it", "what else")) {
            for (int i = history.size() - 1; i >= 0; i--) {
                ChatMessage prev = history.get(i);
                if (prev != null && prev.getContent() != null && !prev.getContent().isBlank()) {
                    return prev.getContent() + " " + currentQuery;
                }
            }
        }
        return currentQuery;
    }

    private boolean isOffTopic(String query) {
        return OFF_TOPIC_PATTERN.matcher(query).find();
    }

    private boolean containsAny(String input, String... keywords) {
        for (String kw : keywords) {
            if (input.contains(kw)) {
                return true;
            }
        }
        return false;
    }

    private boolean isRecommendationQuery(String query) {
        String lower = query.toLowerCase(Locale.ENGLISH);
        boolean hasRecommendationVerb = containsAny(lower,
                "recommend", "recommendation", "suggest", "suggestion",
                "near by", "nearby", "near", "around",
                "list of treks", "which treks", "treks in", "find treks", "options",
                "places to trek", "where can i trek", "treks near", "popular treks", "best treks",
                "provide me treks", "give me treks", "show me treks", "any treks", "what treks", "which trek");

        boolean hasRegionMention = containsAny(lower,
                "nashik", "pune", "mumbai", "himachal", "uttarakhand", "bangalore",
                "karnataka", "manali", "ladakh", "sikkim", "western ghats", "sahyadri", "dehradun");

        boolean hasTrekWord = containsAny(lower, "trek", "treks", "trail", "trails", "hike", "hikes", "mountain", "fort", "peak");

        return hasRecommendationVerb || (hasRegionMention && hasTrekWord);
    }

    private List<String> buildRecommendationFollowUps(List<TrekKnowledgeBaseService.TrekRecommendation> recs) {
        List<String> followUps = new ArrayList<>();
        if (recs != null && !recs.isEmpty()) {
            followUps.add("Tell me more about " + recs.get(0).name);
            if (recs.size() > 1) {
                followUps.add("What is the difficulty of " + recs.get(1).name + "?");
            }
        }
        followUps.add("What gear should I pack for these trails?");
        return followUps;
    }

    private TrekContextPayload synthesizeDefaultContext(String title, String id) {
        TrekContextPayload ctx = new TrekContextPayload();
        ctx.setTrekId(id != null ? id : "1");
        ctx.setTitle(title != null && !title.isBlank() ? title : "Mountain Expedition");
        ctx.setLocation("Pan-India / Global Mountain Trails");
        ctx.setDifficulty("MODERATE");
        ctx.setAltitudeFt(5000);
        ctx.setPricePerSlot(1500.0);
        ctx.setDurationDays(1);
        ctx.setOrganizerName("TrekConnect Certified Guides");
        ctx.setInclusions(Arrays.asList(
                "Mountain breakfast & trail lunch",
                "Certified mountaineer leaders & safety guides",
                "Permits and emergency first aid coordination"
        ));
        ctx.setExclusions(Arrays.asList(
                "Personal gear and mineral water",
                "Personal travel insurance"
        ));
        ctx.setUpcomingDate("Upcoming Weekend");
        return ctx;
    }
}
